changeSet.sql:
CREATE TABLE IF NOT EXISTS HUNTTECH_LLM_CHAT_QUOTA_PERIOD (
    ID uuid PRIMARY KEY, VERSION integer NOT NULL, CREATE_TS timestamp, CREATED_BY varchar(50),
    UPDATE_TS timestamp, UPDATED_BY varchar(50), DELETE_TS timestamp, DELETED_BY varchar(50),
    USER_ID uuid NOT NULL, PERIOD_START date NOT NULL, QUOTA_TOKENS integer NOT NULL,
    RESERVED_TOKENS integer NOT NULL DEFAULT 0, CONSUMED_TOKENS integer NOT NULL DEFAULT 0,
    PENDING_TOKENS integer NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX IF NOT EXISTS UK_HUNTTECH_LLM_CHAT_QUOTA_PERIOD
    ON HUNTTECH_LLM_CHAT_QUOTA_PERIOD (USER_ID, PERIOD_START) WHERE DELETE_TS IS NULL;
CREATE TABLE IF NOT EXISTS HUNTTECH_LLM_USER_QUOTA_OVERRIDE (
    ID uuid PRIMARY KEY, VERSION integer NOT NULL, CREATE_TS timestamp, CREATED_BY varchar(50),
    UPDATE_TS timestamp, UPDATED_BY varchar(50), DELETE_TS timestamp, DELETED_BY varchar(50),
    USER_ID uuid NOT NULL, MONTHLY_QUOTA_TOKENS integer NOT NULL,
    EFFECTIVE_FROM date NOT NULL, EFFECTIVE_TO date, REASON varchar(2000) NOT NULL
);
CREATE INDEX IF NOT EXISTS IDX_HUNTTECH_LLM_USER_QUOTA_OVERRIDE_USER
    ON HUNTTECH_LLM_USER_QUOTA_OVERRIDE (USER_ID, EFFECTIVE_FROM, EFFECTIVE_TO);
CREATE TABLE IF NOT EXISTS HUNTTECH_LLM_CHAT_QUOTA_RESERVATION (
    ID uuid PRIMARY KEY, VERSION integer NOT NULL, CREATE_TS timestamp, CREATED_BY varchar(50),
    UPDATE_TS timestamp, UPDATED_BY varchar(50), DELETE_TS timestamp, DELETED_BY varchar(50),
    PERIOD_ID uuid NOT NULL, CONVERSATION_ID uuid, REQUEST_ID varchar(64) NOT NULL,
    RESERVED_TOKENS integer NOT NULL, SETTLED_TOKENS integer,
    STATUS varchar(32) NOT NULL DEFAULT 'RESERVED'
);
CREATE UNIQUE INDEX IF NOT EXISTS UK_HUNTTECH_LLM_CHAT_QUOTA_REQUEST
    ON HUNTTECH_LLM_CHAT_QUOTA_RESERVATION (REQUEST_ID) WHERE DELETE_TS IS NULL;
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_HUNTTECH_LLM_QUOTA_PERIOD_USER') THEN
        ALTER TABLE HUNTTECH_LLM_CHAT_QUOTA_PERIOD ADD CONSTRAINT FK_HUNTTECH_LLM_QUOTA_PERIOD_USER
            FOREIGN KEY (USER_ID) REFERENCES SEC_USER(ID);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_HUNTTECH_LLM_QUOTA_OVERRIDE_USER') THEN
        ALTER TABLE HUNTTECH_LLM_USER_QUOTA_OVERRIDE ADD CONSTRAINT FK_HUNTTECH_LLM_QUOTA_OVERRIDE_USER
            FOREIGN KEY (USER_ID) REFERENCES SEC_USER(ID);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_HUNTTECH_LLM_QUOTA_RES_PERIOD') THEN
        ALTER TABLE HUNTTECH_LLM_CHAT_QUOTA_RESERVATION ADD CONSTRAINT FK_HUNTTECH_LLM_QUOTA_RES_PERIOD
            FOREIGN KEY (PERIOD_ID) REFERENCES HUNTTECH_LLM_CHAT_QUOTA_PERIOD(ID);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'FK_HUNTTECH_LLM_QUOTA_RES_CONV') THEN
        ALTER TABLE HUNTTECH_LLM_CHAT_QUOTA_RESERVATION ADD CONSTRAINT FK_HUNTTECH_LLM_QUOTA_RES_CONV
            FOREIGN KEY (CONVERSATION_ID) REFERENCES HUNTTECH_LLM_CHAT_CONVERSATION(ID);
    END IF;
END $$;

changeSet.rollback:
DROP TABLE IF EXISTS HUNTTECH_LLM_CHAT_QUOTA_RESERVATION;
DROP TABLE IF EXISTS HUNTTECH_LLM_USER_QUOTA_OVERRIDE;
DROP TABLE IF EXISTS HUNTTECH_LLM_CHAT_QUOTA_PERIOD;
